DROP TABLE IF EXISTS user;
DROP TABLE IF EXISTS film;
DROP TABLE IF EXISTS mpa_rating;
DROP TABLE IF EXISTS genre;
DROP TABLE IF EXISTS like;
DROP TABLE IF EXISTS film_genre;
DROP TABLE IF EXISTS friend;

CREATE TABLE IF NOT EXISTS "user" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"email" VARCHAR(255) NOT NULL,
	"login" VARCHAR(255) NOT NULL,
	"name" VARCHAR(255),
	"birthday" DATE NOT NULL,
);

CREATE TABLE IF NOT EXISTS "film" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" VARCHAR(200) NOT NULL,
	"description" VARCHAR(255) NOT NULL,
	"releaseDate" DATE NOT NULL,
	"duration" BIGINT,
	"mpa_id" INTEGER NOT NULL REFERENCES mpa_rating (id) ON DELETE RESTRICT,
);

CREATE TABLE IF NOT EXISTS "mpa_rating" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
	"name" VARCHAR(255) NOT NULL,
);

CREATE TABLE IF NOT EXISTS "genre" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" VARCHAR(255) NOT NULL,
);

CREATE TABLE IF NOT EXISTS "like" (
	"user_id" INTEGER REFERENCES user (id) ON DELETE CASCADE,
	"film_id" INTEGER REFERENCES film (id) ON DELETE RESTRICT,
	PRIMARY KEY("user_id", "film_id")
);

CREATE TABLE IF NOT EXISTS "film_genre" (
	"film_id" INTEGER REFERENCES film (id) ON DELETE RESTRICT,
	"genre_id" INTEGER REFERENCES genre (id)  ON DELETE CASCADE,
	PRIMARY KEY("film_id", "genre_id")
);

CREATE TABLE IF NOT EXISTS "friend" (
	"user_id" INTEGER REFERENCES user (id) ON DELETE CASCADE,
    "friend_id" INTEGER REFERENCES user (id) ON DELETE CASCADE,
	PRIMARY KEY("user_id", "friend_id")
);